		const dispatches = [dispatch("1", "a", aScript)];
		// 首个进程进入登记表后再预约第二张卡，防止预约和登记身份不同导致重复计名额。
		await waitFor(() => existsSync(join(root, "握手", "a.ready")), 20_000);
