		expect(text).toContain("已记录");
		expect(text).toContain("步骤 s1");
		await expect(
			call(f.tools, "pao_plan_feedback", {
				plan_id: 计划ID,
				action: "record",
				definition_version: 1,
				target_kind: "步骤",
				step_id: "s9",
				text: "不存在的步骤",
			}),
		).rejects.toThrow(/不在计划里/);
		// 计划被改到版本 2 后再用版本 1 提意见：拒（旧意见不能绑到新版本上）。
