				step_id: "s2",
				round: 1,
				file_path: "创作成果/小说/第1章.md",
				text: "缺版本依据",
			}),
		).rejects.toThrow(/version_basis|哪一版/);
		const 首次 = await call(f.tools, "pao_plan_feedback", {
