				target_kind: "步骤",
				step_id: "s1",
				text: "旧版本的确认",
			}),
		).rejects.toThrow(/提交时看到的那一版/);
		// 改标题不动步骤 ID：同一条意见在改标题后仍指向 s1。
		const list = await call(f.tools, "pao_plan_feedback", { plan_id: 计划ID, action: "list" });
		expect(list).toContain("步骤 s1");
		expect(list).toContain("定义版本 1");
