	it("跨实例回执不结算另一条意见：实例对不上就拒", async () => {
		const f = await setup();
		const { 计划ID } = await 建计划(f.tools, "req-fb-instance");
		const 记录 = await call(f.tools, "pao_plan_feedback", {
			plan_id: 计划ID,
			action: "record",
			definition_version: 1,
			step_id: "s1",
