		const first = await 建计划(f.tools, "req-1");
		const replay = await 建计划(f.tools, "req-1");
		expect(replay.计划ID).toBe(first.计划ID);
		expect(replay.text).toContain("回放");
		await expect(
			call(f.tools, "pao_plan_create", {
				request_id: "req-1",
