	it("登记过投递请求 ID 的意见：不带 ID 的回执不结算，错 ID 回执被拒", async () => {
		const f = await setup();
		const { 计划ID } = await 建计划(f.tools, "req-fb-receipt");
		const 记录 = await call(f.tools, "pao_plan_feedback", {
			plan_id: 计划ID,
			action: "record",
			definition_version: 1,
