			deliver_request_id: "deliver-C",
			instance_id: "inst-1",
		});
		const list = await call(f.tools, "pao_plan_feedback", { plan_id: 计划ID, action: "list" });
		expect(list).toContain("投递失败");
		// 另一个实例的回执张冠李戴地来结算这条意见：拒，原状态不被改掉。
		await expect(
			call(f.tools, "pao_plan_feedback", {
				plan_id: 计划ID,
				action: "delivery",
				feedback_id: 意见ID,
				delivered: true,
				result: "另一份执行的送达回执",
				deliver_request_id: "deliver-C",
				instance_id: "inst-2",
