			plan_id: 计划ID,
			request_id: "req-mix-3",
			expected_version: 2,
			action: "revert",
		});
		// 撤回整份才是另一条路：之后这份定义不能再改。
		const 撤回 = await call(f.tools, "pao_plan_update", {
			plan_id: 计划ID,
			request_id: "req-mix-4",
			expected_version: 3,
			action: "undo",
		});
		expect(撤回).toContain("已撤销");
		await expect(
			call(f.tools, "pao_plan_update", {
				plan_id: 计划ID,
				request_id: "req-mix-5",
				expected_version: 4,
				action: "modify",
				display_name: "撤回之后还想改",
