			plan_id: 计划ID,
			request_id: "req-cf-2",
			expected_version: 1,
			action: "modify",
			display_name: "第二版",
		});
		await expect(
			call(f.tools, "pao_plan_update", {
				plan_id: 计划ID,
				request_id: "req-cf-3",
				expected_version: 1,
				action: "revert",
			}),
		).rejects.toThrow(/版本漂移|PLAN_VERSION_CONFLICT/);
		expect(readTemporaryPlan(f.项目根, 计划ID).显示名).toBe("第二版");
	});

	it("revert 也接取消信号与归属校验：受理前取消不落版本，别的会话不能替原主控撤销", async () => {
